import { Trash2 } from "lucide-react";
import { createPortal } from "react-dom";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";

import { QuestionnaireFormProvider } from "@/components/QuestionnaireV2/form/FormContext";

import type { RendererSubject } from "@/components/QuestionnaireV2/form/types";

import { FillCanvas } from "./FillCanvas";
import { FillOutline } from "./FillOutline";
import { FillOutlineRail } from "./FillOutlineRail";
import type { FormStore } from "./StoreRegistrar";
import { StoreRegistrar } from "./StoreRegistrar";
import type { FillFormEntry } from "./formSession";

/**
 * One questionnaire of the session: its own provider (one store), its
 * canvas block in the shared scroll, and its outline pieces PORTALED
 * into the overlay's shared hosts (panel rows + rail ticks) — they must
 * live inside this provider to read this form's store.
 */
export function FillFormSection({
  form,
  subject,
  outlineHost,
  railHost,
  outlineLabel,
  onStore,
  onRemove,
  frozen = false,
}: {
  form: FillFormEntry;
  subject: RendererSubject;
  outlineHost: HTMLElement | null;
  railHost: HTMLElement | null;
  /** Accessible name for this form's outline landmark. The host passes
   *  the questionnaire title once a session holds more than one form, so
   *  the stacked navs stay distinguishable. */
  outlineLabel?: string;
  onStore: (key: string, store: FormStore | null) => void;
  onRemove?: (key: string) => void;
  /** The session is mid-submit — forwarded into this form's renderer
   *  context (freezes every question) and disables the Remove affordance
   *  below, so a click during flight can't drop a form the in-flight
   *  batch already accounts for. */
  frozen?: boolean;
}) {
  const { t } = useTranslation();
  return (
    <QuestionnaireFormProvider
      questionnaire={form.questionnaire}
      mode="fill"
      subject={subject}
      initialResponses={form.initialResponses}
      frozen={frozen}
    >
      <StoreRegistrar formKey={form.key} onStore={onStore} />
      {outlineHost &&
        createPortal(
          <div className="flex flex-col gap-3">
            <p className="truncate pl-2 text-base font-semibold text-gray-950">
              {form.questionnaire.title}
            </p>
            <FillOutline ariaLabel={outlineLabel} />
          </div>,
          outlineHost,
        )}
      {railHost && createPortal(<FillOutlineRail />, railHost)}
      {/* The divider keys off `isPrimary`, not `:first-child` — the
          restore bar and the error panel share this scroll, so DOM
          position is not a reliable "first form" signal. */}
      <section
        data-form-key={form.key}
        className={cn(!form.isPrimary && "border-t border-gray-200 pt-6")}
      >
        {/* Only added forms get a remove affordance; the canvas header already
            names the questionnaire. */}
        {onRemove && !form.isPrimary && (
          <div className="mx-auto mb-2 flex w-full max-w-3xl justify-end">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              // The button sits ABOVE its own form's header, so in reading
              // order it follows the PREVIOUS form's last question — a
              // session with two added forms would otherwise expose two
              // buttons both named just "Remove", and activating the wrong
              // one drops that questionnaire and its answers from the
              // session and from the persisted draft.
              aria-label={t("remove_questionnaire", {
                title: form.questionnaire.title,
              })}
              disabled={frozen}
              onClick={() => onRemove(form.key)}
            >
              <Trash2 className="size-4" />
              {t("remove")}
            </Button>
          </div>
        )}
        <FillCanvas />
      </section>
    </QuestionnaireFormProvider>
  );
}
import { createStore, useStore } from "jotai";
import { useEffect } from "react";

export type FormStore = ReturnType<typeof createStore>;

/** Rendered inside a form's QuestionnaireFormProvider: hands the
 *  per-instance jotai store up to the fill host. The host↔engine surface
 *  is exactly this callback — no engine changes. */
export function StoreRegistrar({
  formKey,
  onStore,
}: {
  formKey: string;
  onStore: (key: string, store: FormStore | null) => void;
}) {
  const store = useStore();
  useEffect(() => {
    onStore(formKey, store);
    return () => onStore(formKey, null);
  }, [formKey, store, onStore]);
  return null;
}
import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { responsesAtom } from "@/components/QuestionnaireV2/form/engine/store";
import { questionnaireKeys } from "@/components/QuestionnaireV2/queryKeys";

import query from "@/Utils/request/query";
import type { QuestionnaireResponse } from "@/types/questionnaire/form";
import type { QuestionnaireRead } from "@/types/questionnaire/questionnaire";
import questionnaireApi from "@/types/questionnaire/questionnaireApi";

import type { FormStore } from "./StoreRegistrar";
import type { DraftFormSnapshot } from "./draft/fillDraftStore";
import {
  mergeDraftIntoSeed,
  preserveExcludedStructured,
} from "./draft/fillDraftStore";
import type { FillFormEntry } from "./formSession";

interface UseFillSessionFormsArgs {
  /** The route-mounted questionnaire — seeds the session's one PRIMARY
   *  form. Only read once (the initial `useState` seed); later identity
   *  changes have no effect. */
  questionnaire: QuestionnaireRead;
  /** Resumed server draft responses, seeded into the primary form at
   *  creation only. */
  serverDraftResponses?: Record<string, QuestionnaireResponse>;
  getStore: (key: string) => FormStore | undefined;
}

/**
 * The fill session's form list plus everything that mutates it: adding a
 * questionnaire (by hand or via a drafted resume), removing one, and the
 * retained-snapshot bookkeeping for forms the draft is still carrying
 * without a live store (a resume whose re-fetch failed).
 */
export function useFillSessionForms({
  questionnaire,
  serverDraftResponses,
  getStore,
}: UseFillSessionFormsArgs) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();

  // The session: the route-mounted questionnaire plus anything added to
  // the same submission. Each entry owns one provider and one store.
  const [forms, setForms] = useState<FillFormEntry[]>(() => [
    {
      key: questionnaire.id,
      questionnaire,
      isPrimary: true,
      initialResponses: serverDraftResponses,
    },
  ]);

  const addQuestionnaire = useCallback(
    (
      added: QuestionnaireRead,
      initialResponses?: Record<string, QuestionnaireResponse>,
    ) => {
      setForms((previous) =>
        previous.some((form) => form.key === added.id)
          ? previous
          : [
              ...previous,
              {
                key: added.id,
                questionnaire: added,
                isPrimary: false,
                initialResponses,
              },
            ],
      );
    },
    [],
  );
  const removeForm = useCallback((key: string) => {
    setForms((previous) =>
      previous.filter((form) => form.key !== key || form.isPrimary),
    );
  }, []);

  // Snapshots that belong to the draft but are not (yet) live forms. They
  // stay in the persisted draft (see `saveFillDraft`'s `retained`) — the
  // ways a resume can fail are NOT the same: a version bump means the
  // answers can no longer be trusted onto the new tree and dropping them
  // is correct, while a network error means try again later, and
  // destroying the clinician's only copy over it is not.
  const [retainedSnapshots, setRetainedSnapshots] = useState<
    DraftFormSnapshot[]
  >([]);
  const dropRetainedSnapshot = useCallback((questionnaireId: string) => {
    setRetainedSnapshots((previous) =>
      previous.filter((entry) => entry.questionnaireId !== questionnaireId),
    );
  }, []);

  // Read by resume callbacks that must see the CURRENT session without
  // re-creating themselves per forms change. Effect-synced, which is
  // enough: every reader is an event-handler-initiated async path that
  // runs strictly after the commit that changed `forms`.
  const formsRef = useRef(forms);
  useEffect(() => {
    formsRef.current = forms;
  }, [forms]);

  /** Resume non-primary snapshots. Each snapshot is retained before refetch
   *  so autosave cannot erase it while it is not yet attached to a live form;
   *  refetch success mounts or merges it, version drift drops it, and fetch
   *  failure keeps it retained for a later retry. */
  const onResumeAddedForms = useCallback(
    (snapshots: DraftFormSnapshot[]) => {
      setRetainedSnapshots((previous) => {
        const seen = new Set(previous.map((entry) => entry.questionnaireId));
        return [
          ...previous,
          ...snapshots.filter(
            (snapshot) => !seen.has(snapshot.questionnaireId),
          ),
        ];
      });
      void (async () => {
        for (const snapshot of snapshots) {
          // Already in the session (the clinician added it by hand before
          // pressing Resume): apply the snapshot to the live store the
          // same way the primary form's resume overlay does — dropping it
          // silently would erase the drafted answers from the stored
          // draft on the very next persist.
          const existing = formsRef.current.find(
            (form) => form.key === snapshot.questionnaireId,
          );
          if (existing) {
            if (
              String(existing.questionnaire.version) !==
              snapshot.questionnaireVersion
            ) {
              dropRetainedSnapshot(snapshot.questionnaireId);
              toast.warning(
                t("fill_draft_form_dropped", {
                  title: existing.questionnaire.title,
                }),
              );
              continue;
            }
            const store = getStore(existing.key);
            if (store) {
              store.set(
                responsesAtom,
                preserveExcludedStructured(
                  store.get(responsesAtom),
                  mergeDraftIntoSeed(
                    existing.questionnaire.questions,
                    snapshot.responses,
                  ),
                ),
              );
            }
            dropRetainedSnapshot(snapshot.questionnaireId);
            continue;
          }
          try {
            const fetched = await queryClient.fetchQuery({
              queryKey: questionnaireKeys.detail(snapshot.questionnaireId),
              queryFn: query(questionnaireApi.get, {
                pathParams: { id: snapshot.questionnaireId },
              }),
            });
            if (String(fetched.version) !== snapshot.questionnaireVersion) {
              dropRetainedSnapshot(snapshot.questionnaireId);
              toast.warning(
                t("fill_draft_form_dropped", { title: fetched.title }),
              );
              continue;
            }
            addQuestionnaire(
              fetched,
              mergeDraftIntoSeed(fetched.questions, snapshot.responses),
            );
            dropRetainedSnapshot(snapshot.questionnaireId);
          } catch {
            // Treat fetch failures as transient: keep the snapshot in the stored
            // draft so the next persist cannot erase it. The stored title is
            // the best available label; fall back to the id when absent.
            toast.warning(
              t("fill_draft_form_unavailable", {
                title: snapshot.title ?? snapshot.questionnaireId,
              }),
            );
          }
        }
      })();
    },
    [queryClient, addQuestionnaire, getStore, dropRetainedSnapshot, t],
  );

  /** The in-session picker's add. When the picked questionnaire matches a
   *  RETAINED snapshot (its resume re-fetch failed earlier), that snapshot
   *  IS the drafted form — seed from it instead of mounting empty, which
   *  would displace the snapshot from the stored draft on the next
   *  persist. A version drift drops it with the same toast as resume. */
  const addQuestionnaireFromPicker = useCallback(
    (selected: QuestionnaireRead) => {
      const snapshot = retainedSnapshots.find(
        (entry) => entry.questionnaireId === selected.id,
      );
      if (!snapshot) {
        addQuestionnaire(selected);
        return;
      }
      dropRetainedSnapshot(selected.id);
      if (String(selected.version) !== snapshot.questionnaireVersion) {
        toast.warning(t("fill_draft_form_dropped", { title: selected.title }));
        addQuestionnaire(selected);
        return;
      }
      addQuestionnaire(
        selected,
        mergeDraftIntoSeed(selected.questions, snapshot.responses),
      );
    },
    [retainedSnapshots, addQuestionnaire, dropRetainedSnapshot, t],
  );

  return {
    forms,
    addQuestionnaire,
    removeForm,
    retainedSnapshots,
    onResumeAddedForms,
    addQuestionnaireFromPicker,
  };
}
/**
 * The form engine's state scope — one Jotai store per mounted form,
 * created by `form/FormContext`'s provider. `responsesAtom` is the
 * per-instance working state: in preview it stays local; in fill mode the
 * host reads it for submission and autosave. `errorsAtom` is written by
 * the fill submit path
 * (`fill/submit/useSubmitFillSession`) with client validation failures
 * and mapped server errors; editing a question's response clears that
 * question's entries (the write path below), so stale errors never outlive
 * the answer they flagged.
 */
import type { Getter, Setter } from "jotai";
import { atom, useAtom, useAtomValue } from "jotai";
import { useMemo } from "react";

import { QuestionValidationError } from "@/types/questionnaire/batch";
import {
  QuestionnaireResponse,
  ResponseValue,
} from "@/types/questionnaire/form";
import { EnableWhen, Question } from "@/types/questionnaire/question";
import { QuestionnaireRead } from "@/types/questionnaire/questionnaire";

export const questionnaireAtom = atom<QuestionnaireRead | null>(null);
export const responsesAtom = atom<Record<string, QuestionnaireResponse>>({});
export const errorsAtom = atom<QuestionValidationError[]>([]);

/**
 * Question ids whose structured slot THREW during render and are now
 * showing the error boundary's notice instead of an input.
 *
 * Submit-time enforcement reads this alongside the subject-mismatch and
 * missing-context cases: all three mean "this question has no input on
 * screen", and requiring an unanswerable question makes the entire form —
 * every other answer included — permanently unsubmittable. Lives in the
 * store because the boundary that discovers it and the validators that
 * must respect it never meet in the component tree.
 */
export const structuredRenderFailedAtom = atom<ReadonlySet<string>>(
  new Set<string>(),
);

/** Record a structured slot's render failure. Idempotent: re-entering the
 *  boundary for a question already marked keeps the same Set identity, so
 *  it cannot loop a subscriber. */
export function useMarkStructuredRenderFailed(questionId: string) {
  const markAtom = useMemo(
    () =>
      atom(null, (get, set) => {
        const failed = get(structuredRenderFailedAtom);
        if (failed.has(questionId)) return;
        set(structuredRenderFailedAtom, new Set(failed).add(questionId));
      }),
    [questionId],
  );
  return useAtom(markAtom)[1];
}

/** Clear a question's render-failed mark — the recovery half of the pair
 *  above. A slot unmounts and remounts whenever enable_when toggles it (or
 *  an ancestor group), and the fresh boundary may well render fine; the
 *  mark must not outlive the notice it described, or a LIVE required input
 *  would stay exempt from validation for the rest of the session.
 *  Idempotent the same way: clearing an unmarked question keeps the Set
 *  identity. */
export function useClearStructuredRenderFailed(questionId: string) {
  const clearAtom = useMemo(
    () =>
      atom(null, (get, set) => {
        const failed = get(structuredRenderFailedAtom);
        if (!failed.has(questionId)) return;
        const next = new Set(failed);
        next.delete(questionId);
        set(structuredRenderFailedAtom, next);
      }),
    [questionId],
  );
  return useAtom(clearAtom)[1];
}

/** link_id → question_id for enable_when lookups — pure so non-atom
 *  consumers (form/validation.ts) share the exact same resolution. */
export function buildLinkIndex(questions: Question[]): Record<string, string> {
  const index: Record<string, string> = {};
  const walk = (list: Question[]) => {
    for (const question of list) {
      index[question.link_id] = question.id;
      if (question.questions) walk(question.questions);
    }
  };
  walk(questions);
  return index;
}

/** link_id → question_id, for enable_when lookups. Internal: consumers
 *  outside the engine call `buildLinkIndex` on the tree they hold. */
const questionIdByLinkIdAtom = atom((get) => {
  const questionnaire = get(questionnaireAtom);
  return questionnaire ? buildLinkIndex(questionnaire.questions) : {};
});

/** Flatten the tree into one response per non-group question, seeding
 *  initial_selected answer options. */
export function initializeResponses(
  questions: Question[],
): Record<string, QuestionnaireResponse> {
  const responses: Record<string, QuestionnaireResponse> = {};
  const walk = (qs: Question[]) => {
    for (const question of qs) {
      if (question.type === "group") {
        walk(question.questions ?? []);
        continue;
      }
      const initial: ResponseValue[] =
        question.answer_option && question.answer_option.length > 0
          ? question.answer_option
              .filter((option) => option.initial_selected)
              .map((option) => ({
                type: "string" as const,
                value: option.value,
                coding: option.code ?? undefined,
              }))
          : [];
      responses[question.id] = {
        question_id: question.id,
        structured_type: question.structured_type ?? null,
        link_id: question.link_id,
        values: initial,
      };
    }
  };
  walk(questions);
  return responses;
}

/** Booleans normalize to "Yes"/"No" and numbers stringify before ANY
 *  operator is applied — matching how recorded response values are
 *  normalized, so enable_when comparisons can match them. */
function normalizeValue(value: unknown): unknown {
  if (typeof value === "boolean") return value ? "Yes" : "No";
  if (typeof value === "number") return value.toString();
  return value;
}

/** Evaluates one enable_when condition against its controller question's
 *  response, matching backend semantics:
 *  - the unanswered-dependency short-circuit (no recorded values → false)
 *    applies to every operator EXCEPT `exists`, which — matching the
 *    backend — evaluates even when the controller is unanswered, since an
 *    `exists:false` dependent must enable precisely then
 *  - ALL of the controller's values are considered (`.some()` /
 *    `.includes()`), not just the first
 *  - `normalizeValue` is applied before every operator other than
 *    `exists`, which only asks whether real content was recorded */
export function evaluateEnableWhen(
  enableWhen: EnableWhen,
  response: QuestionnaireResponse | undefined,
): boolean {
  const dependentValues = response?.values;

  // "exists" must evaluate even when the controller is unanswered: the
  // backend enables an exists:false dependent precisely when the controller
  // has no value. "" is treated as not-existing because serialization drops
  // content-free entries, so the backend never sees them.
  if (enableWhen.operator === "exists") {
    const has =
      !!dependentValues &&
      dependentValues.some(
        (v) => v.value !== undefined && v.value !== null && v.value !== "",
      );
    return enableWhen.answer === false ? !has : has;
  }

  if (!dependentValues || dependentValues.length === 0) return false;

  const normalizedAnswers = dependentValues.map((v) => normalizeValue(v.value));

  switch (enableWhen.operator) {
    case "equals":
      // enableWhen.answer is boolean | string here (EnableWhenBoolean |
      // EnableWhenString). Legacy questionnaires store JSON true/false while
      // responses normalize to "Yes"/"No" — run the stored answer through
      // the same normalization so those conditions can ever match. (Only
      // literal booleans are normalized; string answers pass through
      // untouched, so non-boolean comparisons are unaffected.)
      return normalizedAnswers.includes(normalizeValue(enableWhen.answer));

    case "not_equals":
      // enableWhen.answer is boolean | string here (EnableWhenBoolean | EnableWhenString)
      return !normalizedAnswers.includes(normalizeValue(enableWhen.answer));

    case "greater":
      // enableWhen.answer is number here (EnableWhenNumeric)
      return normalizedAnswers.some(
        (v) => !isNaN(Number(v)) && Number(v) > enableWhen.answer,
      );

    case "less":
      return normalizedAnswers.some(
        (v) => !isNaN(Number(v)) && Number(v) < enableWhen.answer,
      );

    case "greater_or_equals":
      return normalizedAnswers.some(
        (v) => !isNaN(Number(v)) && Number(v) >= enableWhen.answer,
      );

    case "less_or_equals":
      return normalizedAnswers.some(
        (v) => !isNaN(Number(v)) && Number(v) <= enableWhen.answer,
      );

    default:
      return true;
  }
}

/** Drop one question's entries from `errorsAtom` — shared by the response
 *  write path (edit clears the flag) and the structured slot's
 *  `clearError` prop. No-ops when the question has no errors so
 *  subscribers don't re-render on unrelated edits. */
export function clearQuestionErrorsInState(
  get: Getter,
  set: Setter,
  questionId: string,
) {
  const errors = get(errorsAtom);
  if (!errors.some((error) => error.question_id === questionId)) return;
  set(
    errorsAtom,
    errors.filter((error) => error.question_id !== questionId),
  );
}

export function useClearQuestionErrors(questionId: string) {
  const clearAtom = useMemo(
    () =>
      atom(null, (get, set) =>
        clearQuestionErrorsInState(get, set, questionId),
      ),
    [questionId],
  );
  return useAtom(clearAtom)[1];
}

export function useQuestionResponse(questionId: string) {
  const responseAtom = useMemo(
    () =>
      atom(
        (get) => get(responsesAtom)[questionId],
        (get, set, update: Partial<QuestionnaireResponse>) => {
          const previous = get(responsesAtom);
          const current = previous[questionId];
          if (!current) return;
          set(responsesAtom, {
            ...previous,
            [questionId]: { ...current, ...update },
          });
          // An edit supersedes any validation error recorded against this
          // question (client or server) — clear just its entries.
          clearQuestionErrorsInState(get, set, questionId);
        },
      ),
    [questionId],
  );
  return useAtom(responseAtom);
}

/** Shared enable_when resolution — extracted (unchanged semantics) so every
 *  consumer (useQuestionEnabled, the visibility hooks below, and
 *  form/validation.ts) evaluates identically. Exported so the fill path
 *  never re-derives it from evaluateEnableWhen. */
export function isQuestionEnabledInState(
  question: Question,
  responses: Record<string, QuestionnaireResponse>,
  linkIndex: Record<string, string>,
): boolean {
  if (!question.enable_when?.length) return true;
  const results = question.enable_when.map((condition) =>
    evaluateEnableWhen(
      condition,
      responses[linkIndex[condition.question] ?? ""],
    ),
  );
  return question.enable_behavior === "any"
    ? results.some(Boolean)
    : results.every(Boolean);
}

export function useQuestionEnabled(question: Question): boolean {
  const enabledAtom = useMemo(
    () =>
      atom((get) =>
        isQuestionEnabledInState(
          question,
          get(responsesAtom),
          get(questionIdByLinkIdAtom),
        ),
      ),
    [question],
  );
  return useAtomValue(enabledAtom);
}

/**
 * Ids of every question in the tree (any depth) currently hidden by its
 * enable_when conditions — i.e. disabled and not `disabled_display:
 * "protected"` (protected questions still render, greyed). The tree navs
 * use this to drop rows for questions that aren't on the canvas.
 */
export function useHiddenQuestionIds(): Set<string> {
  const hiddenIdsAtom = useMemo(
    () =>
      atom((get) => {
        const questionnaire = get(questionnaireAtom);
        const hidden = new Set<string>();
        if (!questionnaire) return hidden;
        const responses = get(responsesAtom);
        const linkIndex = get(questionIdByLinkIdAtom);
        const walk = (questions: Question[]) => {
          for (const question of questions) {
            if (
              question.disabled_display !== "protected" &&
              !isQuestionEnabledInState(question, responses, linkIndex)
            ) {
              hidden.add(question.id);
            }
            walk(question.questions ?? []);
          }
        };
        walk(questionnaire.questions);
        return hidden;
      }),
    [],
  );
  return useAtomValue(hiddenIdsAtom);
}

/**
 * Whether any top-level question is currently on the canvas. Boolean (not
 * the index array) so the value is Object.is-stable across answer edits —
 * the one-scroll canvas body subscribes to this, and answering a question
 * must not re-render every block.
 */
export function useHasVisibleTopLevelQuestions(): boolean {
  const hasVisibleAtom = useMemo(
    () =>
      atom((get) => {
        const questionnaire = get(questionnaireAtom);
        if (!questionnaire) return false;
        const responses = get(responsesAtom);
        const linkIndex = get(questionIdByLinkIdAtom);
        return questionnaire.questions.some(
          (question) =>
            question.disabled_display === "protected" ||
            isQuestionEnabledInState(question, responses, linkIndex),
        );
      }),
    [],
  );
  return useAtomValue(hasVisibleAtom);
}

/** Whether one recorded entry carries an actual answer — non-empty
 *  scalar, or a non-empty array (structured/repeat values). Shared with
 *  form/validation.ts so the required check and the outline's completion
 *  icons agree on what "answered" means. */
export function entryHasContent(entry: ResponseValue): boolean {
  if (entry.value === undefined || entry.value === null || entry.value === "")
    return false;
  return !Array.isArray(entry.value) || entry.value.length > 0;
}

/**
 * Ids of every question with at least one recorded answer — the fill
 * outline's completion icons subscribe to this. Derived per render of the
 * consuming component only (one subscriber: the outline), so the fresh
 * Set identity per responses change is fine.
 */
export function useAnsweredQuestionIds(): Set<string> {
  const answeredAtom = useMemo(
    () =>
      atom((get) => {
        const answered = new Set<string>();
        for (const [id, response] of Object.entries(get(responsesAtom))) {
          if (response.values.some(entryHasContent)) answered.add(id);
        }
        return answered;
      }),
    [],
  );
  return useAtomValue(answeredAtom);
}

export function useQuestionErrors(questionId: string) {
  const questionErrorsAtom = useMemo(
    () =>
      atom((get) =>
        get(errorsAtom).filter((error) => error.question_id === questionId),
      ),
    [questionId],
  );
  return useAtomValue(questionErrorsAtom);
}

