  // the same submission (add/remove, retained-draft-snapshot bookkeeping,
  // the async resume-added-forms path) — see useFillSessionForms.ts.
  const {
    forms,
    removeForm,
    retainedSnapshots,
    onResumeAddedForms,
    addQuestionnaireFromPicker,
  } = useFillSessionForms({
    questionnaire,
    serverDraftResponses,
    getStore,
  });

