                    <DraftRestoreBar
                      draft={autosave.restoredDraft}
                      onResume={autosave.resumeRestoredDraft}
                      onDiscard={autosave.discardRestoredDraft}
                      onDismiss={autosave.dismissRestoreBar}
                      frozen={frozen}
                    />
                  )}
