                  {forms.map((form) => (
                    <FillFormSection
                      key={form.key}
                      form={form}
                      subject={rendererSubject}
                      outlineHost={outlineHost}
                      railHost={railHost}
                      outlineLabel={
                        forms.length > 1 ? form.questionnaire.title : undefined
                      }
                      onStore={handleStore}
                      onRemove={forms.length > 1 ? removeForm : undefined}
                      frozen={frozen}
                    />
