                            type="button"
                            variant="outline"
                            className="border-primary-600 text-primary-800"
                            disabled={frozen}
                          >
                            <Plus className="size-4" />
                            {t("add_questionnaire")}
                          </Button>
                        }
                      />
                    </div>
                  )}
