          <TabsContent
            value="history"
            forceMount={historyMounted || undefined}
            className="mt-3 min-h-0 flex-1 overflow-y-auto px-4 pb-6 data-[state=inactive]:hidden md:px-6"
          >
            {historyMounted && (
              <ClinicalHistoryTab
                patientId={patientId}
                facilityId={facilityId}
              />
            )}
          </TabsContent>
        )}
      </FillShell>
    </Tabs>
  );
}

