import type { QuestionnaireResponse } from "@/types/questionnaire/form";

export interface FillDraftScope {
  userId: string;
  subjectKey: string;
  entryQuestionnaireId: string;
  /** Query context that changes which record the structured widgets edit. */
  contextKey?: string;
}

export function fillDraftScopeKey(scope: FillDraftScope): string {
  const base = `${scope.userId}--${scope.subjectKey}--${scope.entryQuestionnaireId}`;
  return scope.contextKey
    ? `${base}--context=${encodeURIComponent(scope.contextKey)}`
    : base;
}

// This module must stay free of `structured/registry` (directly or
// transitively): `serverDraft.test.ts` runs under plain `node --test`, and
// the registry pulls every core definition's component tree.

/** JSON round-trips Dates to ISO strings; date/dateTime entries revive to
 *  Date objects so the inputs' discriminant checks keep working. Shared by
 *  the local-draft store and the server-draft (`?continue_draft=`) restore
 *  path, whose dump went through the same JSON flattening. */
export function reviveDraftResponses(
  responses: Record<string, QuestionnaireResponse>,
): Record<string, QuestionnaireResponse> {
  for (const response of Object.values(responses)) {
    // Server dumps are untyped blobs — a `values`-less entry is possible
    // and must not throw the whole encounter overview.
    for (const entry of response.values ?? []) {
      // Fresh from JSON.parse the declared Date is actually a string —
      // read through `unknown` at this one boundary.
      const raw = (entry as { value?: unknown }).value;
      if (
        (entry.type === "date" || entry.type === "dateTime") &&
        typeof raw === "string"
      ) {
        const revived = new Date(raw);
        entry.value = isNaN(revived.getTime()) ? undefined : revived;
      }
    }
  }
  return responses;
}
/**
 * Dependency-free local draft cache helpers: key prefix, expiry and sweeps.
 * Other-user login removes unrelated drafts on shared devices; sign-out and
 * app update remove all drafts; expired or corrupt entries are swept at boot.
 */
export const FILL_DRAFT_PREFIX = "care_qn_fill_draft--";

const TTL_MS = 24 * 60 * 60 * 1000;

export function isFillDraftExpired(savedAt: string): boolean {
  const saved = new Date(savedAt).getTime();
  return isNaN(saved) || Date.now() - saved > TTL_MS;
}

/** Prefix sweep — registered at signOut and app update so draft data
 *  never outlives a deliberately-ended session. */
export function clearQuestionnaireFillDrafts(): void {
  for (const key of Object.keys(localStorage)) {
    if (key.startsWith(FILL_DRAFT_PREFIX)) localStorage.removeItem(key);
  }
}

/**
 * Prefix sweep scoped to every OTHER user — registered at the post-auth-
 * success boundary (JWT sign-in and MFA verification) so a login by a
 * DIFFERENT account on a shared device gets a clean slate, while the
 * just-authenticated user's own draft (e.g. one left at the login form by
 * a session expiry) survives re-login. A key whose userId segment cannot
 * be parsed is treated as untrusted and removed, same as a corrupt entry.
 */
export function clearOtherUsersFillDrafts(currentUserId: string): void {
  for (const key of Object.keys(localStorage)) {
    if (!key.startsWith(FILL_DRAFT_PREFIX)) continue;
    const userId = key.slice(FILL_DRAFT_PREFIX.length).split("--")[0];
    if (!userId || userId !== currentUserId) {
      localStorage.removeItem(key);
    }
  }
}

/** Drop expired/corrupt drafts (any user) — run on fill page mount and at
 *  provider boot, independent of auth outcome. */
export function sweepExpiredFillDrafts(): void {
  for (const key of Object.keys(localStorage)) {
    if (!key.startsWith(FILL_DRAFT_PREFIX)) continue;
    try {
      const draft = JSON.parse(localStorage.getItem(key) ?? "") as {
        savedAt?: string;
      };
      if (!draft.savedAt || isFillDraftExpired(draft.savedAt)) {
        localStorage.removeItem(key);
      }
    } catch {
      localStorage.removeItem(key);
    }
  }
}
import { entryHasContent } from "@/components/QuestionnaireV2/form/engine/store";
import { resolveStructuredType } from "@/components/QuestionnaireV2/structured/registry";

import type { QuestionnaireResponse } from "@/types/questionnaire/form";
import type { Question } from "@/types/questionnaire/question";
import type { QuestionnaireRead } from "@/types/questionnaire/questionnaire";

import type { DroppedDraftAnswer } from "./draftMerge";
import { draftResponseHasContent, mergeDraftResponses } from "./draftMerge";
import { FILL_DRAFT_PREFIX, isFillDraftExpired } from "./fillDraftCache";
import type { FillDraftScope } from "./fillDraftCore";
import { fillDraftScopeKey, reviveDraftResponses } from "./fillDraftCore";
import {
  draftIntentResponse,
  initializeStructuredResponse,
} from "./structuredDraft";

/**
 * Local fill drafts — the crash/reload safety net. Draft data lives in
 * localStorage only under this prefix, scoped per user + subject + entry
 * questionnaire, TTL-bounded, and swept on an OTHER user's login, on
 * signOut and on app update — every eviction hook is deliberate; a new
 * session boundary must join the sweep list. Expired drafts are swept at
 * boot regardless of auth outcome. A user's OWN drafts deliberately
 * survive their own re-login — that is the crash/session-expiry recovery
 * this layer exists for, not a bug (see `fillDraftCache.ts`).
 *
 * One key holds the WHOLE fill session: the route-mounted questionnaire
 * plus every questionnaire added to the same submission.
 */
const SCHEMA_VERSION = 2;

export type { FillDraftScope } from "./fillDraftCore";

export interface DraftFormSnapshot {
  questionnaireId: string;
  /** `QuestionnaireRead.version` — a version bump invalidates this form
   *  (the read spec exposes no modified_date yet). */
  questionnaireVersion: string;
  /** The questionnaire's title as it read when the draft was written —
   *  the only human name available when a resume can no longer FETCH the
   *  questionnaire. Optional because v2 drafts written before this field
   *  existed are still valid; every reader must fall back. */
  title?: string;
  responses: Record<string, QuestionnaireResponse>;
  structuredSkipped: boolean;
}

interface StoredFillDraft {
  schemaVersion: number;
  savedAt: string;
  userId: string;
  subjectKey: string;
  entryQuestionnaireId: string;
  contextKey?: string;
  forms: DraftFormSnapshot[];
}

export interface LoadedFillDraft {
  forms: DraftFormSnapshot[];
  savedAt: string;
  /** True when the saved session had structured answers the draft could
   *  not carry (draftPolicy "exclude") — the restore bar says so. */
  structuredSkipped: boolean;
  /**
   * Drop notice for the primary form, computed against the questionnaire's
   * current questions before the clinician chooses Resume or Discard.
   * Added forms are merged later when the host re-fetches them on resume.
   */
  dropped: DroppedDraftAnswer[];
}

function draftKey(scope: FillDraftScope): string {
  return `${FILL_DRAFT_PREFIX}${fillDraftScopeKey(scope)}`;
}

/** File payloads and plugin types that opt out cannot round-trip through
 * JSON. Unknown plugin types are excluded until their definition is loaded. */
function isDraftExcluded(response: QuestionnaireResponse): boolean {
  if (!response.structured_type) return false;
  const resolved = resolveStructuredType(response.structured_type);
  return !resolved || resolved.draftPolicy === "exclude";
}

/** Keep serializable responses and all notes; annotate omitted file/plugin
 * values so recovery can explain which sections need re-entry. */
function partitionForDraft(responses: Record<string, QuestionnaireResponse>): {
  safe: Record<string, QuestionnaireResponse>;
  structuredSkipped: boolean;
} {
  const safe: Record<string, QuestionnaireResponse> = {};
  let structuredSkipped = false;
  for (const [id, response] of Object.entries(responses)) {
    if (isDraftExcluded(response)) {
      if (response.values.some(entryHasContent)) structuredSkipped = true;
      // Files/plugin values may be unsafe to serialize, but their notes
      // are ordinary clinician input and must survive reloads.
      safe[id] = { ...response, values: [], draft_context: undefined };
      continue;
    }
    safe[id] = response;
  }
  return { safe, structuredSkipped };
}

/** Restore structured answers against live server baselines. Values that
 * cannot be drafted (files and excluded plugins) remain in the live store;
 * serializable edits rebase onto freshly fetched clinical records. */
export function preserveExcludedStructured(
  current: Record<string, QuestionnaireResponse>,
  next: Record<string, QuestionnaireResponse>,
