import careConfig from "@careConfig";
import { useQuery } from "@tanstack/react-query";
import { ShieldAlert } from "lucide-react";
import { useTranslation } from "react-i18next";

import { PLUGIN_Component } from "@/PluginEngine";

import { EmptyState } from "@/components/ui/empty-state";
import { ScrollArea } from "@/components/ui/scroll-area";

import QuestionnaireResponsesList from "@/components/Facility/ConsultationDetails/QuestionnaireResponsesList";
import { AllergyList } from "@/components/Patient/allergy/list";
import { DiagnosisList } from "@/components/Patient/diagnosis/list";
import { SymptomsList } from "@/components/Patient/symptoms/list";
import { VitalsList } from "@/components/Patient/vitals/list";
import { ObservationPlotConfig } from "@/types/emr/observation/observation";

import { ClinicalHistoryOverview } from "@/pages/Encounters/tabs/overview/clinical-history-overview";
import { FavoriteFormsQuickActions } from "@/pages/Encounters/tabs/overview/FavoriteFormsQuickActions";
import { FormSubmissionDrafts } from "@/pages/Encounters/tabs/overview/FormSubmissionDrafts";
import { QuickActions } from "@/pages/Encounters/tabs/overview/quick-actions";
import { SummaryPanel } from "@/pages/Encounters/tabs/overview/summary-panel";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import EncounterOverviewDevices from "@/pages/Facility/settings/devices/components/EncounterOverviewDevices";
import { inactiveEncounterStatus } from "@/types/emr/encounter/encounter";

export const EncounterOverviewTab = () => {
  const { t } = useTranslation();
  const {
    selectedEncounter: encounter,
    patientId,
    selectedEncounterId: encounterId,
    canReadSelectedEncounter: canAccess,
    canWriteSelectedEncounter: canWrite,
    canReadClinicalData,
  } = useEncounter();

  const { data: plotsConfig } = useQuery<ObservationPlotConfig>({
    queryKey: ["plots-config"],
    queryFn: () => fetch(careConfig.plotsConfigUrl).then((res) => res.json()),
    enabled: canReadClinicalData,
  });

  const vitalGroups =
    plotsConfig?.find((plot) => plot.id === "primary-parameters")?.groups || [];

  return (
    <div className="flex gap-3 @max-md:w-full">
      {canReadClinicalData ? (
        <div className="flex-1 xl:pr-3 overflow-y-auto xl:h-[calc(100vh-14rem-var(--encounter-header-offset))]">
          <div className="flex flex-col gap-4">
            {canWrite && <QuickActions />}
            {canWrite && <FavoriteFormsQuickActions />}
            {encounter && (
              <PLUGIN_Component
                __name="EncounterOverviewTop"
                encounter={encounter}
                patientId={patientId}
                encounterId={encounterId}
              />
            )}
            {<ClinicalHistoryOverview />}

            <div className="xl:hidden">
              <SummaryPanel />
            </div>

            {
              <div className="flex flex-col gap-8 overflow-x-auto">
                {/* Show preview of devices associated with the encounter */}
                {encounter && (
                  <EncounterOverviewDevices encounter={encounter} />
                )}
                {encounter &&
                  !inactiveEncounterStatus.includes(encounter.status) && (
                    <FormSubmissionDrafts
                      facilityId={encounter.facility.id}
                      patientId={patientId}
                      encounterId={encounterId}
                    />
                  )}
                {/* Clinical informations */}
                <AllergyList
                  patientId={patientId}
                  encounterId={encounterId}
                  readOnly={!canWrite}
                  encounterStatus={encounter?.status}
                  showViewEncounter={false}
                />
                <SymptomsList
                  patientId={patientId}
                  encounterId={encounterId}
                  readOnly={!canWrite}
                  showViewEncounter={false}
                />
                <DiagnosisList
                  patientId={patientId}
                  encounterId={encounterId}
                  readOnly={!canWrite}
                  showViewEncounter={false}
                />
                <VitalsList
                  patientId={patientId}
                  encounterId={encounterId}
                  codeGroups={vitalGroups}
                />
                <QuestionnaireResponsesList
                  encounterId={encounterId}
                  patientId={patientId}
                  canAccess={canAccess}
                />
              </div>
            }
          </div>
        </div>
      ) : (
        <div className="flex-1 xl:pr-3 flex items-center justify-center">
          <EmptyState
            icon={<ShieldAlert className="text-gray-400 size-8" />}
            title={t("no_permission_to_view_clinical_data")}
            description={t("no_permission_to_view_clinical_data_description")}
            className="h-full w-full bg-transparent"
          />
        </div>
      )}

      <ScrollArea className="w-72 hidden xl:block h-[calc(100vh-14rem-var(--encounter-header-offset))]">
        <SummaryPanel />
      </ScrollArea>
    </div>
  );
};
import { QuestionnaireScope } from "@/types/questionnaire/questionnaire";

/**
 * Query-key factory for every questionnaire-v2 query. All keys share the
 * `questionnaireKeys.all` root so `invalidateQueries({ queryKey:
 * questionnaireKeys.all })` reaches lists, details, organizations and
 * revisions structurally — a key built outside this factory would silently
 * opt out of that invalidation (and of the documented
 * setQueryData-before-invalidate save sequence in useUpdateQuestionnaire).
 *
 * Module-local by design: the repo has no global key-factory convention, so
 * this only standardizes the QuestionnaireV2 subtree.
 */
export const questionnaireKeys = {
  all: ["questionnairesV2"] as const,
  list: (scope: QuestionnaireScope, filters: unknown) =>
    [
      ...questionnaireKeys.all,
      scope.authContext,
      // Both scoping ids ride along: `authContext` alone does not separate
      // two facility_organization mounts from each other, and a list cached
      // under one organization must never be served to another.
      scope.facilityId,
      scope.facilityOrganizationId,
      filters,
    ] as const,
  detail: (id: string) => [...questionnaireKeys.all, "detail", id] as const,
  /**
   * `variant` is load-bearing, not decoration: the instance
   * (`get_organizations`) and facility (`get_facility_organizations`)
   * endpoints return different collections for the SAME questionnaire id,
   * so one questionnaire opened from both mounts in a session would
   * otherwise serve each other's payload from cache.
   */
  organizations: (id: string, variant: "instance" | "facility") =>
    [...questionnaireKeys.all, "organizations", variant, id] as const,
  revisions: (id: string) =>
    [...questionnaireKeys.all, "revisions", id] as const,
  revisionDetail: (id: string | undefined) =>
    [...questionnaireKeys.all, "revision-detail", id] as const,
};

/**
 * The action registry (`action_configuration/instructions|fields`) — what
 * the backend can run and what a condition may reference. Static per
 * deployment, so consumers set a long `staleTime`.
 */
export const actionRegistryKeys = {
  all: ["actionRegistry"] as const,
  instructions: () => [...actionRegistryKeys.all, "instructions"] as const,
  fields: () => [...actionRegistryKeys.all, "fields"] as const,
};

/**
 * Keys for the server-side `form_submission` drafts the fill page saves and
 * resumes (`useSaveServerDraft`, `?continue_draft=`) and the encounter
 * overview lists. Hand-built literals here were a correctness hazard: the
 * only thing separating the detail key from the list key was singular vs
 * plural, spelled out across three files.
 */
export const formSubmissionKeys = {
  all: ["formSubmissions"] as const,
  /**
   * Prefix for every list query — the invalidation target after a draft
   * save. Deliberately NARROWER than `all`: invalidating a DETAIL query
   * from a page that navigates away in the same tick makes React Query
   * cancel the resulting refetch and revert the cache to the pre-save dump
   * (see `useSaveServerDraft`), so a re-resume would seed stale answers.
   */
  lists: () => [...formSubmissionKeys.all, "list"] as const,
  list: (encounterId: string) =>
    [...formSubmissionKeys.lists(), encounterId] as const,
  detail: (id: string | undefined) =>
    [...formSubmissionKeys.all, "detail", id] as const,
};
import React from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { ButtonVariant, buttonVariants } from "@/components/ui/button";

interface ConfirmActionDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description: React.ReactNode;
  onConfirm: () => void;
  cancelText?: string;
  confirmText: string;
  variant?: ButtonVariant;
  disabled?: boolean;
  hideCancel?: boolean;
}

export default function ConfirmActionDialog({
  open,
  onOpenChange,
  title,
  description,
  onConfirm,
  cancelText,
  confirmText,
  variant = "primary",
  disabled,
  hideCancel,
}: ConfirmActionDialogProps) {
  const { t } = useTranslation();
  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle className="capitalize">{title}</AlertDialogTitle>
          <AlertDialogDescription>{description}</AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          {!hideCancel && (
            <AlertDialogCancel>{cancelText || t("cancel")}</AlertDialogCancel>
          )}
          <AlertDialogAction
            onClick={onConfirm}
            className={cn(buttonVariants({ variant }))}
            disabled={disabled}
          >
            {confirmText}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}
import { createContext, useContext } from "react";

import {
  LoginRequest,
  LoginResponse,
  MfaLoginRequest,
} from "@/types/auth/auth";
import { TokenData } from "@/types/otp/otp";
import { CurrentUserRead } from "@/types/user/user";

export interface AuthContextType {
  user: CurrentUserRead | undefined;
  signIn: (creds: LoginRequest) => Promise<LoginResponse>;
  verifyMFA: (data: MfaLoginRequest) => Promise<LoginResponse>;
  isAuthenticating: boolean;
  isVerifyingMFA: boolean;
  /** Deliberate sign-out — also clears local questionnaire fill drafts. */
  signOut: () => Promise<void>;
  /** Same session teardown for the INVOLUNTARY paths (session expiry, a
   *  cross-tab token removal), which leave fill drafts in place so work
   *  interrupted by an expiry can be recovered after re-login. */
  endSessionKeepingDrafts: () => Promise<void>;
  patientLogin: (tokenData: TokenData, redirectUrl: string) => void;
  patientToken: TokenData | null;
}

export const AuthUserContext = createContext<AuthContextType | null>(null);

export const useAuthContext = () => {
  const ctx = useContext(AuthUserContext);
  if (!ctx) {
    throw new Error(
      "'useAuthContext' must be used within 'AuthUserProvider' only",
    );
  }
  return ctx;
};

export default function useAuthUser() {
  const user = useAuthContext().user;
  if (!user) {
    throw new Error("'useAuthUser' must be used within 'AppRouter' only");
  }
  return user;
}
