    forms,
    getStore,
    subject,
    continueDraftId,
    onSaved: () => {
      autosave.finishDraft();
      navigate(exitTarget);
    },
  });

  // Both saves capture the current answers and clear the local draft on
  // success. Freeze editing until either request settles so later edits
  // cannot be discarded with a payload that did not contain them.
  const frozen = isPending || serverDraftSave.isSavingDraft;

  useNavigationPrompt(
    autosave.dirty && !import.meta.env.DEV,
    t("unsaved_changes"),
  );

  // What a federated agent (Scribe) may do to this session, and the one
  // validated path for doing it. Nothing is registered for a session with
  // no patient in scope, so those mounts hand the plugin an empty list.
  const { descriptors, invoke } = useFillActions({
    subject,
    forms,
    getStore,
    frozen,
  });

  return (
    // Tabs wraps the shell so its Radix context reaches both the strip in

item.formatted_output:
    // otherwise clear is already gone.
    restorePendingRef.current = false;
    setRestoreDismissed(true);
    persistNow();
  }, [persistNow]);

  const dismissRestoreBar = useCallback(() => {
    restorePendingRef.current = false;
    setRestoreDismissed(true);
    persistNow();
  }, [persistNow]);

  /** Apply the restored draft — the prompt bar's Resume affordance. The
   *  primary form's snapshot lands in the live store through the shared
   *  overlay rule; every other snapshot goes back to the host, which
   *  re-adds those questionnaires seeded from their snapshots. */
  const resumeRestoredDraft = useCallback(() => {
    const draft = restoredDraftRef.current;
    if (!draft) return;
    const primary = forms.find((form) => form.isPrimary);
    const addedSnapshots: DraftFormSnapshot[] = [];
    for (const snapshot of draft.forms) {
      if (primary && snapshot.questionnaireId === primary.key) {
        const store = getStore(primary.key);
        if (store) {
          store.set(
            responsesAtom,
            preserveExcludedStructured(
              store.get(responsesAtom),
              mergeDraftIntoSeed(
                primary.questionnaire.questions,
                snapshot.responses,
              ),
            ),
          );
        }
        continue;
      }
      addedSnapshots.push(snapshot);
    }
    if (addedSnapshots.length > 0) onResumeAddedForms(addedSnapshots);
    setDirty(true);
    setRestoreDismissed(true);
  }, [forms, getStore, onResumeAddedForms]);

  return {
    /** Any edit since mount — drives the Draft chip. A merely-detected
     *  draft is NOT dirty; the chip lights only after Resume or an edit. */
    dirty,
    restoredDraft: restoreDismissed ? undefined : restoredDraft,
    discardRestoredDraft,
    dismissRestoreBar,
    resumeRestoredDraft,
    /** For the submit-success path: the draft served its purpose. */
    finishDraft,
  };
}
