      savedAt: draft.modified_date || draft.created_date,
      formCount: 1,
      url: `${fillBase}/${encodeURIComponent(questionnaire.id)}?continue_draft=${encodeURIComponent(draft.id)}`,
      draft,
    });
  }
  rows.sort((a, b) => Date.parse(b.savedAt) - Date.parse(a.savedAt));

