import { clearQueuePractitionerCache } from "@/atoms/queuePractitionerAtom";
import { clearScheduleServiceTypeCache } from "@/atoms/scheduleServiceTypeAtom";
import { clearQuestionnaireFillDrafts } from "@/components/QuestionnaireV2/fill/draft/fillDraftCache";
import { clearQueryPersistenceCache } from "@/Utils/request/queryClient";

import queryClient from "@/Utils/request/queryClient";

// Constants
export const APP_VERSION_KEY = "app-version";
export const APP_LAST_UPDATED_KEY = "app-last-updated";
export const APP_UPDATED_KEY = "app-updated";
export const BUILD_META_URL = "/build-meta.json";

// Types
export interface AppVersionInfo {
  version: string;
  lastUpdatedAt: string;
}

export interface BuildMeta {
  version: string;
  built_at: string;
}

/**
 * Get stored version info from localStorage
 */
export function getStoredVersionInfo(): AppVersionInfo | null {
  const version = localStorage.getItem(APP_VERSION_KEY);
  const lastUpdatedAt = localStorage.getItem(APP_LAST_UPDATED_KEY);

  if (!version || !lastUpdatedAt) {
    return null;
  }

  return { version, lastUpdatedAt };
}

/**
 * Set version info in localStorage
 */
export function setStoredVersionInfo(info: AppVersionInfo): void {
  localStorage.setItem(APP_VERSION_KEY, info.version);
  localStorage.setItem(APP_LAST_UPDATED_KEY, info.lastUpdatedAt);
}

/**
 * Mark that the app was just updated (for showing success toast after reload)
 */
export function setAppUpdatedFlag(): void {
  localStorage.setItem(APP_UPDATED_KEY, "true");
}

/**
 * Check and clear the app updated flag
 */
export function checkAndClearAppUpdatedFlag(): boolean {
  const wasUpdated = localStorage.getItem(APP_UPDATED_KEY) === "true";
  if (wasUpdated) {
    localStorage.removeItem(APP_UPDATED_KEY);
  }
  return wasUpdated;
}

/**
 * Fetch build meta from server with no-cache headers
 */
export async function fetchBuildMeta(): Promise<BuildMeta> {
  const response = await fetch(BUILD_META_URL, {
    cache: "no-store",
    headers: {
      "Cache-Control": "no-cache",
      Pragma: "no-cache",
    },
  });

  if (!response.ok) {
    throw new Error(`Failed to fetch build meta: ${response.status}`);
  }

  return response.json();
}

/**
 * Clear all caches including browser caches, service workers, and query cache
 */
export async function clearAllCaches(): Promise<void> {
  // Clear browser caches
  if ("caches" in window) {
    const cacheNames = await caches.keys();
    await Promise.all(cacheNames.map((name) => caches.delete(name)));
  }

  // Unregister service workers
  if ("serviceWorker" in navigator) {
    const registrations = await navigator.serviceWorker.getRegistrations();
    await Promise.all(registrations.map((reg) => reg.unregister()));
  }

  // Clear React Query cache
  queryClient.clear();
  clearQueryPersistenceCache();
  clearScheduleServiceTypeCache();
  clearQueuePractitionerCache();
  clearQuestionnaireFillDrafts();
}

/**
 * Perform app update: clear caches, set flag, and reload
 */
export async function performAppUpdate(newVersion: string): Promise<void> {
  await clearAllCaches();
  setStoredVersionInfo({
    version: newVersion,
    lastUpdatedAt: new Date().toISOString(),
  });
  setAppUpdatedFlag();
  window.location.reload();
}
import { useStore } from "jotai";
import { Suspense, useCallback, useEffect, useSyncExternalStore } from "react";
import { useTranslation } from "react-i18next";

import { PluginErrorBoundary } from "@/components/Common/PluginErrorBoundary";
import { FormSkeleton } from "@/components/Common/SkeletonLoading";

import { initializeStructuredResponse } from "@/components/QuestionnaireV2/fill/draft/structuredDraft";
import {
  responsesAtom,
  useClearQuestionErrors,
  useClearStructuredRenderFailed,
  useMarkStructuredRenderFailed,
  useQuestionErrors,
  useQuestionResponse,
} from "@/components/QuestionnaireV2/form/engine/store";
import {
  getStructuredTypesVersion,
  subscribeToStructuredTypes,
} from "@/components/QuestionnaireV2/structured/pluginRegistry";
import {
  resolveStructuredSlotState,
  structuredTypeLabel,
} from "@/components/QuestionnaireV2/structured/registry";

import type { ResponseValue } from "@/types/questionnaire/form";
import type { Question } from "@/types/questionnaire/question";

import { useFormRenderer } from "./FormContext";

/**
 * Clears the question's render-failed mark when it mounts. Rendered INSIDE
 * the error boundary, beside the structured component: if the component
 * throws during the mounting render, the whole subtree — this probe
 * included — is discarded before effects run, so the clear only ever fires
 * for a commit whose input actually made it to the screen. That placement
 * is what makes the mark track reality across an unmount/remount cycle
 * (enable_when toggling the question): a recovered slot un-exempts itself,
 * a still-broken one re-marks via the boundary's onError.
 */
function ClearRenderFailedOnMount({ questionId }: { questionId: string }) {
  const clearRenderFailed = useClearStructuredRenderFailed(questionId);
  useEffect(() => {
    clearRenderFailed();
  }, [clearRenderFailed]);
  return null;
}

/**
 * Renders core and plugin structured questions from a resolved definition.
 * `onChange` is memoized for adapter callbacks, and preview withholds
 * questionnaire ids so template CRUD stays off the builder surface.
 */
export function StructuredSlot({
  question,
  disabled,
}: {
  question: Question;
  disabled: boolean;
}) {
  const { t } = useTranslation();
  const { mode, subject, questionnaire } = useFormRenderer();
  // Plugins register their types as their remote module loads, which can
  // land after this slot first renders — subscribing re-resolves instead of
  // leaving a permanent "requires a plugin" notice on screen.
  useSyncExternalStore(
    subscribeToStructuredTypes,
    getStructuredTypesVersion,
    getStructuredTypesVersion,
  );
  const [response, updateResponse] = useQuestionResponse(question.id);
  const store = useStore();
  const errors = useQuestionErrors(question.id);
  const clearErrors = useClearQuestionErrors(question.id);
  const markRenderFailed = useMarkStructuredRenderFailed(question.id);

  const handleChange = useCallback(
    (values: ResponseValue[], note?: string) =>
      updateResponse(note === undefined ? { values } : { values, note }),
    [updateResponse],
  );
  const handleInitializeResponse = useCallback(
    (values: ResponseValue[]) => {
      const current = store.get(responsesAtom)[question.id];
      if (current)
        updateResponse(initializeStructuredResponse(current, values));
    },
    [question.id, store, updateResponse],
  );

  // The same resolution submit-time enforcement runs — see
  // `StructuredSlotState`'s parity note. Whatever this returns other than
  // "ready" renders a notice, not an input: the question cannot be
  // answered here, but a REQUIRED one still hard-blocks the submit by name
  // (`collectStructuredErrors`) — this slot no longer waives it.
  const state = question.structured_type
    ? resolveStructuredSlotState(
        question.structured_type,
        questionnaire.subject_type,
        subject,
      )
    : undefined;

  // A type this deployment doesn't have (plugin disabled or removed after
  // the questionnaire was authored) — say so instead of rendering nothing,
  // which would read as an empty question. The notice's closing sentence
  // must not contradict `collectStructuredErrors`' blocking error below
  // it: a non-required slot promises its entries are skipped, a required
  // one says the opposite — the form can't be saved until this loads —
  // so each notice key has a `_required` twin instead of one sentence
  // trying to cover both outcomes.
  if (state?.kind === "unknown_type") {
    return (
      <div className="rounded-lg border border-dashed border-amber-300 bg-amber-50 p-4 text-sm text-amber-800">
        {t(
          question.required
            ? "structured_type_plugin_missing_required"
            : "structured_type_plugin_missing",
          { type: question.structured_type },
        )}
      </div>
    );
  }
  if (!state || !response) return null;

  const { definition } = state;
  const label = structuredTypeLabel(definition.type, t);

  if (state.kind === "subject_mismatch") {
    return (
      <div className="rounded-lg border border-dashed border-gray-300 bg-gray-50 p-4 text-sm text-gray-500">
        {t(
          question.required
            ? "structured_type_subject_mismatch_required"
            : "structured_type_subject_mismatch",
          {
            type: label,
            // The raw enum reads as jargon in a clinician-facing notice;
            // the studio's own subject picker labels these the same way.
            subject: t(questionnaire.subject_type),
          },
        )}
      </div>
    );
  }

  if (state.kind === "missing_context") {
    return (
      <div className="rounded-lg border border-dashed border-gray-300 bg-gray-50 p-4 text-sm text-gray-500">
        <p className="font-medium text-gray-700">{label}</p>
        <p>
          {t(
            question.required
              ? "structured_question_requires_context_required"
              : "structured_question_requires_context",
            {
              contexts: state.missing
                .map((key) => t(`context__${key}`))
                .join(", "),
            },
          )}
        </p>
      </div>
    );
  }

  const Component = definition.component;
  return (
    // Every other structured failure mode on this page degrades in place
    // (missing type → amber notice, subject mismatch → gray notice, thrown
    // validate/buildRequests → question-scoped error). A render throw was
    // the one that didn't: it unwound to the router's page boundary and
    // replaced the whole fill session — every other form, every answer
    // already typed — with the generic error screen. Contain it here, in
    // the same dashed notice the other degradations use.
    <PluginErrorBoundary
      pluginName={definition.type}
      // Once the notice is showing there is no input to answer — same as
      // the subject-mismatch and missing-context notices above. A REQUIRED
      // question still hard-blocks the submit by name for this reason
      // (`collectStructuredErrors`); marking it here only tells that
      // validator (and `collectRequiredErrors`, staying out of the way)
      // which slots are in this state.
      onError={markRenderFailed}
      // `resolveStructuredType` hands back a stable reference per
      // registration (see its memoization) — a new one only when a plugin
      // re-registers this type, which is exactly the moment a previously
      // thrown component deserves a fresh mount instead of a permanent
      // notice.
      resetKey={definition}
      fallback={
        <div className="rounded-lg border border-dashed border-amber-300 bg-amber-50 p-4 text-sm text-amber-800">
          <p className="font-medium">{label}</p>
          <p>
            {t(
              question.required
                ? "structured_question_render_failed_required"
                : "structured_question_render_failed",
            )}
          </p>
        </div>
      }
    >
      <ClearRenderFailedOnMount questionId={question.id} />
      {/* Plugin components arrive through React.lazy — the boundary keeps
          a still-loading remote from suspending the whole form. */}
      <Suspense fallback={<FormSkeleton rows={2} />}>
        <Component
          question={question}
          response={response}
          onChange={handleChange}
          onInitializeResponse={handleInitializeResponse}
          disabled={disabled}
          errors={errors}
          clearError={clearErrors}
          patientId={subject.patientId}
          encounterId={subject.encounterId}
          facilityId={subject.facilityId}
          {...(mode === "fill"
            ? {
                questionnaireId: questionnaire.id,
                questionnaireSlug: questionnaire.slug,
              }
            : {})}
        />
      </Suspense>
    </PluginErrorBoundary>
  );
}
import type { ComponentType } from "react";

import type { QuestionValidationError } from "@/types/questionnaire/batch";
import type {
  QuestionnaireResponse,
  ResponseValue,
} from "@/types/questionnaire/form";
import type { Question } from "@/types/questionnaire/question";
import type { SubjectType } from "@/types/questionnaire/questionnaire";
import type { StructuredQuestionType } from "@/types/questionnaire/structured";

import type { ApplyChargeItemDefinitionRequest } from "@/types/billing/chargeItem/chargeItem";
import type { AllergyIntoleranceRequest } from "@/types/emr/allergyIntolerance/allergyIntolerance";
import type { DiagnosisRequest } from "@/types/emr/diagnosis/diagnosis";
import type { EncounterEdit } from "@/types/emr/encounter/encounter";
import type { MedicationRequestCreate } from "@/types/emr/medicationRequest/medicationRequest";
import type { MedicationStatementRequest } from "@/types/emr/medicationStatement";
import type { ServiceRequestApplyActivityDefinitionForm } from "@/types/emr/serviceRequest/serviceRequest";
import type { SymptomRequest } from "@/types/emr/symptom/symptom";
import type { FileUploadQuestion } from "@/types/files/file";
import type { CreateAppointmentQuestion } from "@/types/scheduling/schedule";

/** Subject ids a structured type needs before it can render at all —
 *  `StructuredSlot` shows the "requires context" placeholder when the
 *  mount subject lacks one of these. */
export type StructuredContextKey = "patientId" | "encounterId" | "facilityId";

/** What the UI edits per type — one entry of `values[0].value`'s array.
 *  (`time_of_death` stores plain strings.) The sole such map: the legacy
 *  one in `components/Questionnaire/structured/` went with the legacy fill
 *  stack that was its only consumer. */
export interface StructuredDataMap {
  allergy_intolerance: AllergyIntoleranceRequest;
  medication_request: MedicationRequestCreate;
  medication_statement: MedicationStatementRequest;
  symptom: SymptomRequest;
  diagnosis: DiagnosisRequest;
  encounter: EncounterEdit;
  appointment: CreateAppointmentQuestion;
  files: FileUploadQuestion;
  time_of_death: string;
  service_request: ServiceRequestApplyActivityDefinitionForm;
  charge_item: ApplyChargeItemDefinitionRequest;
}

export type DataTypeFor<K extends StructuredQuestionType> =
  StructuredDataMap[K];

/** One entry of the submit batch (`POST /api/v1/batch_requests/`). */
export interface StructuredBatchEntry {
  url: string;
  method: "POST" | "PUT" | "PATCH";
  reference_id: string;
  body: unknown;
}

/** Context `buildRequests` composes URLs/bodies from.
 *
 *  `patientId` is GUARANTEED present for a type whose `subjects` are
 *  patient and/or encounter — which is every core type, so core
 *  definitions only need a one-line guard to narrow it. It is optional
 *  because a PLUGIN type may declare a resource subject
 *  (location/device/facility): the studio lets it be authored there and
 *  the slot renders it, so its `buildRequests` must be reachable on a
 *  mount that has no patient at all.
 *
 *  `questionId` keys `reference_id` so server errors map back to the exact
 *  question instance — two questions of the same structured type no longer
 *  collide. */
export interface StructuredRequestContext {
  patientId?: string;
  encounterId?: string;
  facilityId?: string;
  questionId: string;
}

export function structuredReferenceId(
  type: StructuredQuestionType,
  questionId: string,
): string {
  return `structured:${type}:${questionId}`;
}

/** The prop bag `StructuredSlot` hands every structured input. Adapters
 *  narrow it to the legacy component's own props (subject ids are
 *  guaranteed present for the keys the definition `requires`). */
export interface StructuredInputProps {
  question: Question;
  response: QuestionnaireResponse;
  /** Memoized by the slot; adapters preserve this callback identity. */
  onChange: (values: ResponseValue[], note?: string) => void;
  /** Record server-prefilled values separately from clinician edits. */
  onInitializeResponse?: (values: ResponseValue[]) => void;
  disabled: boolean;
  errors: QuestionValidationError[];
  clearError: () => void;
  patientId?: string;
  encounterId?: string;
  facilityId?: string;
  /** Fill mode only — template CRUD (real POSTs) stays off preview. */
  questionnaireId?: string;
  questionnaireSlug?: string;
}

/**
 * Everything one structured question type needs, in one place: how it
 * renders, what context it needs, how it validates, how it turns data
 * into API requests, and whether its values are safe to persist in a
 * local draft. The registry is a total record over
 * `StructuredQuestionType` — adding a member to the union refuses to
 * compile until a definition exists.
 */
export interface StructuredTypeDefinition<
  K extends StructuredQuestionType = StructuredQuestionType,
> {
  type: K;
  component: ComponentType<StructuredInputProps>;
  requires: readonly StructuredContextKey[];
  /** Questionnaire subject types this structured type may appear on —
   *  gates the studio's picker and the fill renderer. */
  subjects: readonly SubjectType[];
  /**
   * `"serialize"` — values are plain user input, safe to store in a local
   * draft and restore later.
   * Server-backed values retain their initial context so draft recovery
   * can reconcile clinician edits with fresh clinical records.
   * `"exclude"` — values cannot round-trip through JSON (for example,
   * `files` carries raw `File` objects).
   */
  draftPolicy: "serialize" | "exclude";
  /** Submit-time validation over the recorded entries (already narrowed
   *  to this type's data shape). Optional — types without client rules
   *  rely on server-side validation. */
  validate?: (
    data: DataTypeFor<K>[],
    questionId: string,
    required: boolean,
  ) => QuestionValidationError[];
  /** Turn recorded entries into raw batch requests. May return [] when
   *  the context it needs is missing or nothing changed (dirty-row
   *  filtering). Async because some types transform payloads (files →
   *  base64). */
  buildRequests: (
    data: DataTypeFor<K>[],
    context: StructuredRequestContext,
  ) => Promise<StructuredBatchEntry[]>;
}

