import { faker } from "@faker-js/faker";
import { expect, type Page, test } from "@playwright/test";
import {
  adminApiHeaders,
  apiBaseUrl,
  questionBlock,
} from "tests/helper/questionnaireV2";
import { getEncounterId } from "tests/support/encounterId";
import { getFacilityId } from "tests/support/facilityId";
import { getPatientId } from "tests/support/patientId";

test.use({ storageState: "tests/.auth/user.json" });

const TOGGLE_LABEL = "Show clinical section";
const SECTION_LABEL = "Clinical section";

async function openConditionalSection(page: Page, structuredType: string) {
  const suffix = faker.string.alphanumeric(12).toLowerCase();
  const response = await fetch(`${apiBaseUrl()}/api/v1/questionnaire/`, {
    method: "POST",
    headers: adminApiHeaders(),
    body: JSON.stringify({
      title: `E2E Structured State ${suffix}`,
      slug: `e2e-structured-state-${suffix}`,
      status: "active",
      subject_type: "encounter",
      auth_context: "instance",
      questions: [
        {
          id: faker.string.uuid(),
          link_id: "SHOW",
          text: TOGGLE_LABEL,
          type: "boolean",
          required: false,
          questions: [],
        },
        {
          id: faker.string.uuid(),
          link_id: "SECTION",
          text: SECTION_LABEL,
          type: "structured",
          structured_type: structuredType,
          required: false,
          enable_when: [{ question: "SHOW", operator: "equals", answer: true }],
          questions: [],
        },
      ],
    }),
  });
  expect(response.ok, await response.clone().text()).toBeTruthy();
  const questionnaire = (await response.json()) as { id: string };
  await page.goto(
    `/facility/${getFacilityId()}/patient/${getPatientId()}/encounter/${getEncounterId()}/questionnaire/${questionnaire.id}`,
  );
  await questionBlock(page, TOGGLE_LABEL)
    .getByRole("radio", { name: "Yes", exact: true })
    .click();
  await expect(questionBlock(page, SECTION_LABEL)).toBeVisible();
}

async function remountSection(page: Page) {
  const toggle = questionBlock(page, TOGGLE_LABEL);
  await toggle.getByRole("radio", { name: "No", exact: true }).click();
  await expect(questionBlock(page, SECTION_LABEL)).toHaveCount(0);
  await toggle.getByRole("radio", { name: "Yes", exact: true }).click();
  await expect(questionBlock(page, SECTION_LABEL)).toBeVisible();
}

test("file names and selections survive conditional remount and adding another file", async ({
  page,
}) => {
  await openConditionalSection(page, "files");
  const section = questionBlock(page, SECTION_LABEL);
  await section.locator('input[type="file"]').setInputFiles({
    name: "first.txt",
    mimeType: "text/plain",
    buffer: Buffer.from("first attachment"),
  });
  const names = section.getByPlaceholder("File Name", { exact: true });
  await names.first().fill("Original attachment");
  await remountSection(page);
  await expect(names).toHaveCount(1);
  await expect(names.first()).toHaveValue("Original attachment");
  await section.locator('input[type="file"]').setInputFiles({
    name: "second.txt",
    mimeType: "text/plain",
    buffer: Buffer.from("second attachment"),
  });
  await expect(names).toHaveCount(2);
  await expect(names.first()).toHaveValue("Original attachment");
  await expect(section.getByText("first.txt", { exact: true })).toBeVisible();
  await expect(section.getByText("second.txt", { exact: true })).toBeVisible();
});

test("encounter edits survive conditional remount without resetting from the cached encounter", async ({
  page,
}) => {
  await openConditionalSection(page, "encounter");
  const identifier = questionBlock(page, SECTION_LABEL).getByPlaceholder(
    "Ip/op/obs/emr number",
    { exact: true },
  );
  const editedIdentifier = `REMOUNT-${faker.string.alphanumeric(8)}`;
  await identifier.fill(editedIdentifier);
  await remountSection(page);
  await expect(identifier).toHaveValue(editedIdentifier);
});

test("diagnosis edits survive remount and local draft recovery while fresh server fields are reconciled", async ({
  page,
}) => {
  let serverSeverity = "moderate";
  const diagnosisId = faker.string.uuid();
  await page.route(
    `**/api/v1/patient/${getPatientId()}/diagnosis/**`,
    async (route) => {
      await route.fulfill({
        json: {
          count: 1,
          next: null,
          previous: null,
          results: [
            {
              id: diagnosisId,
              code: {
                code: "E2E-DRAFT",
                system: "test",
                display: "Draft recovery diagnosis",
              },
              clinical_status: "active",
              verification_status: "confirmed",
              severity: serverSeverity,
              category: "encounter_diagnosis",
              onset: { onset_datetime: "2025-01-01" },
              note: "Initial server note",
              encounter: getEncounterId(),
              created_date: "2025-01-01T00:00:00Z",
            },
          ],
        },
      });
    },
  );
  await openConditionalSection(page, "diagnosis");
  const section = questionBlock(page, SECTION_LABEL);
  const note = section.getByRole("textbox", {
    name: "Enter additional notes",
    exact: true,
  });
  await expect(note).toHaveValue("Initial server note");
  await note.fill("Unsaved clinician note");
  await remountSection(page);
  await expect(note).toHaveValue("Unsaved clinician note");

  serverSeverity = "severe";
  await page.reload();
  await expect(page.getByText(/unsaved entry from/i)).toBeVisible();
  await page.getByRole("button", { name: /resume/i }).click();
  await expect(note).toHaveValue("Unsaved clinician note");
  await expect(
    section
      .getByRole("row", { name: /Draft recovery diagnosis/ })
      .getByRole("combobox")
      .nth(1),
  ).toHaveText("Severe");
});

test("charge rows and quantities survive remount and local draft recovery", async ({
  page,
}) => {
  const definition = {
    id: faker.string.uuid(),
    slug: "e2e-draft-charge",
    title: "Draft recovery charge",
    status: "active",
    price_components: [],
    category: null,
    tags: [],
  };
  await page.route(
    `**/api/v1/facility/${getFacilityId()}/charge_item_definition/**`,
    async (route) => {
      await route.fulfill({
        json: new URL(route.request().url()).pathname.endsWith(
          `/${definition.slug}/`,
        )
          ? definition
          : { count: 1, results: [definition] },
      });
    },
  );
  await openConditionalSection(page, "charge_item");
  const section = questionBlock(page, SECTION_LABEL);
  await section
    .getByRole("combobox")
    .filter({ hasText: /Add charges/ })
    .click();
  await page.getByRole("dialog").getByRole("combobox").fill(definition.title);
  await page
    .getByRole("option", { name: definition.title, exact: true })
    .click();
  const row = section.getByRole("row", { name: /Draft recovery charge/ });
  const quantity = row.getByRole("spinbutton");
  await quantity.fill("3");
  await remountSection(page);
  await expect(quantity).toHaveValue("3");
  await page.reload();
  await expect(page.getByText(/unsaved entry from/i)).toBeVisible();
  await page.getByRole("button", { name: /resume/i }).click();
  await expect(quantity).toHaveValue("3");
});

test("prescription drafts stay isolated across A, B, and new-prescription query changes", async ({
  page,
}) => {
  const prescriptionA = faker.string.uuid();
  const prescriptionB = faker.string.uuid();
  const medicationA = faker.string.uuid();
  const medicationB = faker.string.uuid();
  const fillPath = `/facility/${getFacilityId()}/patient/${getPatientId()}/encounter/${getEncounterId()}/questionnaire/medication_request`;

  await page.route(
    `**/api/v1/patient/${getPatientId()}/medication/request/**`,
    async (route) => {
      const prescription = new URL(route.request().url()).searchParams.get(
        "prescription",
      );
      const label = prescription === prescriptionA ? "A" : "B";
      await route.fulfill({
        json: {
          count: 1,
          results: [
            {
              id: label === "A" ? medicationA : medicationB,
              medication: {
                code: `RX-${label}`,
                system: "test",
                display: `Prescription ${label} medication`,
              },
              status: "active",
              intent: "order",
              category: "outpatient",
              priority: "routine",
              do_not_perform: false,
              dosage_instruction: [{ as_needed_boolean: false }],
              authored_on: "2025-01-01T00:00:00Z",
              note: `Server note ${label}`,
            },
          ],
        },
      });
    },
  );
  await page.route(
    `**/api/v1/patient/${getPatientId()}/medication/prescription/**`,
    async (route) => {
      await route.fulfill({ json: { status: "active", medications: [] } });
    },
  );

  const section = questionBlock(page, "Medication Request");
  const note = section.getByPlaceholder("Enter additional notes", {
    exact: true,
  });
  const navigateInPlace = async (prescription?: string) => {
    // Exercise the router's query-only navigation without a document reload:
    // the previous form provider must unmount and flush its own draft scope.
    await page.evaluate(
      (path) => {
        window.history.pushState({}, "", path);
        window.dispatchEvent(new PopStateEvent("popstate"));
      },
      `${fillPath}${prescription ? `?prescription=${prescription}` : ""}`,
    );
  };

  await page.goto(`${fillPath}?prescription=${prescriptionA}`);
  await expect(note).toHaveValue("Server note A");
  await note.fill("Unsaved prescription A note");

  await navigateInPlace(prescriptionB);
  await expect(note).toHaveValue("Server note B");
  await expect(
    section.getByText("Prescription A medication", { exact: true }),
  ).toHaveCount(0);
  await expect(page.getByText(/unsaved entry from/i)).toHaveCount(0);
  await note.fill("Unsaved prescription B note");

  await navigateInPlace();
  await expect(note).toHaveCount(0);
  await expect(section.getByText(/Prescription [AB] medication/)).toHaveCount(
    0,
  );
  await expect(page.getByText(/unsaved entry from/i)).toHaveCount(0);

  for (const [prescription, label] of [
    [prescriptionA, "A"],
    [prescriptionB, "B"],
  ]) {
    await navigateInPlace(prescription);
    await expect(page.getByText(/unsaved entry from/i)).toBeVisible();
    await page.getByRole("button", { name: /resume/i }).click();
    await expect(note).toHaveValue(`Unsaved prescription ${label} note`);
    await expect(
      section.getByText(
        `Prescription ${label === "A" ? "B" : "A"} medication`,
        { exact: true },
      ),
    ).toHaveCount(0);
  }
});
import { Plus, X } from "lucide-react";
import { memo, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { cn } from "@/lib/utils";

import { emptyEntry } from "@/components/QuestionnaireV2/form/engine/inputs/withEntryAt";
import { QUESTION_TYPE_COMPONENTS } from "@/components/QuestionnaireV2/form/engine/questionTypeRegistry";
import {
  EMPTY_ROW_KEYS,
  dropRowKey,
  growRowKeys,
} from "@/components/QuestionnaireV2/form/engine/rowKeys";
import { sanitizeStylingClasses } from "@/components/QuestionnaireV2/form/engine/sanitizeStylingClasses";
import {
  useQuestionEnabled,
  useQuestionErrors,
  useQuestionResponse,
} from "@/components/QuestionnaireV2/form/engine/store";

import type { Question } from "@/types/questionnaire/question";

import { useFormChrome } from "./chrome";
import { useFormRenderer } from "./FormContext";
import { NoteControl } from "./NoteControl";
import { SectionCard } from "./SectionCard";
import { StructuredSlot } from "./StructuredSlot";

export interface QuestionBlockProps {
  question: Question;
  parentId: string | null;
  index: number;
  siblingCount: number;
  depth: number;
  /** Dotted ordinal matching the tree nav (e.g. "8." or "7.1."). */
  number?: string;
}

/**
 * One node of the questionnaire tree on the one-scroll canvas — the full
 * renderer's counterpart to the old paginated QuestionField. Same response
 * semantics (single-entry vs positional repeats, chip inputs, structured
 * slot, sanitized styling), new layout, plus the two canvas seams: chrome
 * wrapping and `revealHidden`/`inert` handling from the form context.
 */
export const QuestionBlock = memo(function QuestionBlock(
  props: QuestionBlockProps,
) {
  const { question, depth, number } = props;
  const { mode, revealHidden, frozen } = useFormRenderer();
  const { QuestionShell } = useFormChrome();
  const enabled = useQuestionEnabled(question);

  const hiddenByLogic = !enabled && question.disabled_display !== "protected";
  if (hiddenByLogic && !revealHidden) return null;

  // Two distinct states, and only inputs take both: `locked` is the question's
  // persistent inertness, `frozen` is the in-flight submit. Anything that
  // decides whether a control RENDERS must read `locked` alone — the freeze
  // lasts one request, and a control that unmounts for it reflows the form
  // mid-submit and flickers back on failure.
  const locked = mode === "readonly" || question.read_only === true || !enabled;
  const effectiveDisabled = locked || frozen;

  const wrap = (children: React.ReactNode) =>
    QuestionShell ? (
      <QuestionShell {...props} hiddenByLogic={hiddenByLogic}>
        {children}
      </QuestionShell>
    ) : (
      children
    );

  if (question.type === "group") {
    return wrap(
      <SectionCard
        question={question}
        depth={depth}
        disabled={effectiveDisabled}
        number={number}
      />,
    );
  }

  return wrap(
    <LeafBlock
      question={question}
      depth={depth}
      number={number}
      effectiveDisabled={effectiveDisabled}
      locked={locked}
    />,
  );
});

/**
 * The non-group body — a separate component so the response and error
 * store subscriptions only exist for questions that actually record
 * answers (groups returned above without ever mounting them).
 */
function LeafBlock({
  question,
  depth,
  number,
  effectiveDisabled,
  locked,
}: {
  question: Question;
  depth: number;
  number?: string;
  effectiveDisabled: boolean;
  locked: boolean;
}) {
  const { t } = useTranslation();
  const { inert } = useFormRenderer();
  const { QuestionAnnotation } = useFormChrome();
  const errors = useQuestionErrors(question.id);
  // Only written by repeating questions; read for entry counts.
  const [response, updateResponse] = useQuestionResponse(question.id);

  const InputComponent = QUESTION_TYPE_COMPONENTS[question.type];
  // Programmatic label association: text-like inputs take `id={inputId}` for
  // the htmlFor pairing; chip groups (boolean/choice) reference `labelId`
  // via aria-labelledby on their radiogroup container instead.
  const inputId = `question-input-${question.id}`;
  const labelId = `question-label-${question.id}`;

  // Repeating questions render one input per value entry, except fixed-option
  // choices, which render every selected value through their own multi-select
  // control. The branch matches ChoiceInput: `answer_option` wins over
  // `answer_value_set` when both are present.
  const isSelfManagedChoice =
    question.type === "choice" && !!question.answer_option?.length;

  const isMultiEntry =
    !!InputComponent &&
    question.repeats === true &&
    question.type !== "structured" &&
    question.type !== "display" &&
    !isSelfManagedChoice;

  const entryCount = Math.max(response?.values.length ?? 0, 1);
  const canRemoveEntries = (response?.values.length ?? 0) > 1;

  // Rows that appeared since the last render claim a key here — see
  // rowKeys.ts for why an index key cannot survive a removal.
  const [rowKeys, setRowKeys] = useState(EMPTY_ROW_KEYS);
  const visibleRowKeys = growRowKeys(rowKeys, entryCount);
  if (visibleRowKeys !== rowKeys) setRowKeys(visibleRowKeys);

  // Adding from an empty response materializes the on-screen placeholder entry
  // too, so the new row never swallows the one the user was looking at.
  const handleAddEntry = () => {
    const current = response?.values ?? [];
    const next = current.length === 0 ? [emptyEntry()] : [...current];
    next.push(emptyEntry());
    updateResponse({ values: next });
  };

  const handleRemoveEntry = (index: number) => {
    setRowKeys((current) => dropRowKey(current, entryCount, index));
    updateResponse({
      values: (response?.values ?? []).filter((_, i) => i !== index),
    });
  };

  return (
    // data-question-id is the renderer's stable per-question DOM anchor —
    // hosts scroll to it (outline selection, future scroll-to-error) and
    // tests scope input assertions with it.
    <div
      data-question-id={question.id}
      className={cn(
        "space-y-1.5",
        depth <= 1 && "rounded-lg border border-gray-200 bg-white p-3.5",
        // Questionnaire-authored classes — sanitized, never raw.
        sanitizeStylingClasses(question.styling_metadata?.containerClasses),
      )}
    >
      <div className="flex items-start gap-2">
        <span
          aria-hidden
          className="mt-1 h-3.5 w-0.5 shrink-0 rounded-full bg-primary-600"
        />
        {number && (
          <span className="shrink-0 text-sm font-medium text-gray-500 tabular-nums">
            {number}
          </span>
        )}
        <label
          id={labelId}
          htmlFor={inputId}
          className="text-sm font-medium text-gray-800"
        >
          {question.text}
        </label>
        {/* Visual-only: the programmatic required state is aria-required
            on the input itself (every engine input sets it). */}
        {question.required && (
          <span aria-hidden className="text-red-500">
            *
          </span>
        )}
        {/* Question-level unit display for types without answer-time unit pickers. */}
        {question.unit?.code && (
          <span className="text-sm text-gray-500">({question.unit.code})</span>
        )}
      </div>
      {question.description && (
        <p className="pl-2.5 text-xs text-gray-500">{question.description}</p>
      )}
      {QuestionAnnotation && <QuestionAnnotation question={question} />}
      {/* The interactive area: inert on the builder's edit canvas so clicks
          fall through to the selection chrome and none of these controls
          surface in the a11y tree. */}
      <div inert={inert || undefined}>
        {question.type === "structured" ? (
          <StructuredSlot question={question} disabled={effectiveDisabled} />
        ) : isMultiEntry ? (
          <div className="space-y-2">
            {Array.from({ length: entryCount }, (_, index) => (
              <div
                key={visibleRowKeys.keys[index]}
                className="flex items-center gap-2"
              >
                <div className="min-w-0 flex-1">
                  <InputComponent
                    question={question}
                    disabled={effectiveDisabled}
                    inputId={index === 0 ? inputId : `${inputId}-${index}`}
                    labelId={labelId}
                    valueIndex={index}
                  />
                </div>
                {canRemoveEntries && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="shrink-0"
                    disabled={effectiveDisabled}
                    onClick={() => handleRemoveEntry(index)}
                    aria-label={t("remove")}
                  >
                    <X className="size-4" />
                  </Button>
                )}
              </div>
            ))}
            <div className="flex items-center gap-2">
              <Button
                type="button"
                variant="outline"
                size="sm"
                disabled={effectiveDisabled}
                onClick={handleAddEntry}
              >
                <Plus className="size-4" />
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { useHasVisibleTopLevelQuestions } from "@/components/QuestionnaireV2/form/engine/store";
import { countLeafQuestions } from "@/components/QuestionnaireV2/shared/questionTree";

import type { QuestionnaireResponse } from "@/types/questionnaire/form";
import type { QuestionnaireRead } from "@/types/questionnaire/questionnaire";

import { FormChrome, FormChromeProvider, useFormChrome } from "./chrome";
import { QuestionnaireFormProvider, useFormRenderer } from "./FormContext";
import { QuestionBlock } from "./QuestionBlock";
import type { FormMode, RendererSubject } from "./types";

/** Presentation slots shared by every canvas entry point. */
export interface CanvasSlots {
  /** Replaces the default "no questions" text (the studio passes its
   *  add-first/import affordances). */
  emptyState?: React.ReactNode;
  /** Hide the questionnaire title/description header (hosts that already
   *  show them elsewhere). */
  hideHeader?: boolean;
  /** Right-aligned hint next to the header (the studio's "click any
   *  question to edit it"). */
  headerHint?: React.ReactNode;
  className?: string;
}

export interface QuestionnaireFormRendererProps extends CanvasSlots {
  questionnaire: QuestionnaireRead;
  mode: FormMode;
  subject?: RendererSubject;
  /** Builder edit canvas: render enable_when-hidden questions too. */
  revealHidden?: boolean;
  /** Builder edit canvas: inputs visible but non-interactive. */
  inert?: boolean;
  /** Creation-time seed overrides (a restored draft) — forwarded verbatim
   *  to the provider, which applies them once. See FormContext. */
  initialResponses?: Record<string, QuestionnaireResponse>;
  /** Decoration seam — see chrome.tsx. */
  chrome?: FormChrome;
}

/**
 * The renderer: the whole questionnaire on one scroll — top-level groups
 * as section cards, everything live against the per-instance store. The
 * studio canvas, the read-only previews and the fill flow all mount this
 * one module; there is no second renderer.
 */
export function QuestionnaireFormRenderer({
  questionnaire,
  mode,
  subject,
  revealHidden,
  inert,
  initialResponses,
  chrome = {},
  emptyState,
  hideHeader,
  headerHint,
  className,
}: QuestionnaireFormRendererProps) {
  return (
    <QuestionnaireFormProvider
      questionnaire={questionnaire}
      mode={mode}
      subject={subject}
      revealHidden={revealHidden}
      inert={inert}
      initialResponses={initialResponses}
    >
      <FormChromeProvider chrome={chrome}>
        <CanvasBody
          emptyState={emptyState}
          hideHeader={hideHeader}
          headerHint={headerHint}
          className={className}
        />
      </FormChromeProvider>
    </QuestionnaireFormProvider>
  );
}

/**
 * The canvas body for hosts that mount `QuestionnaireFormProvider`
 * themselves — the studio does, so its outline and canvas share one store
 * (the outline's preview mode reads live enable_when hidden ids).
 */
export function QuestionnaireFormCanvas({
  chrome = {},
  emptyState,
  hideHeader,
  headerHint,
  className,
}: CanvasSlots & { chrome?: FormChrome }) {
  return (
    <FormChromeProvider chrome={chrome}>
      <CanvasBody
        emptyState={emptyState}
        hideHeader={hideHeader}
        headerHint={headerHint}
        className={className}
      />
    </FormChromeProvider>
  );
}

function CanvasBody({
  emptyState,
  hideHeader,
  headerHint,
  className,
}: CanvasSlots) {
  const { t } = useTranslation();
  const { questionnaire, revealHidden } = useFormRenderer();
  const { AppendZone } = useFormChrome();
  const hasVisibleQuestions = useHasVisibleTopLevelQuestions();
  const questions = questionnaire.questions;

  const sectionCount = questions.filter(
    (question) => question.type === "group",
  ).length;
  const countLine = [
    sectionCount > 0 && t("n_sections", { count: sectionCount }),
    t("n_questions", { count: countLeafQuestions(questions) }),
  ]
    .filter(Boolean)
    .join(" · ");

  const header = !hideHeader && (
    <div className="flex items-baseline justify-between gap-3 pb-4">
      <div className="min-w-0 space-y-1">
        <h2 className="text-lg font-semibold tracking-tight text-gray-900">
          {questionnaire.title}
        </h2>
        {questionnaire.description && (
          <p className="text-sm text-gray-500">{questionnaire.description}</p>
        )}
        {questions.length > 0 && (
          <p className="text-xs text-gray-400">{countLine}</p>
        )}
      </div>
      {headerHint && (
        <div className="shrink-0 text-xs text-gray-400">{headerHint}</div>
      )}
    </div>
  );

  if (questions.length === 0) {
    return (
      <div className={cn("mx-auto w-full max-w-3xl", className)}>
        {header}
        {emptyState ?? (
          <div className="rounded-lg bg-white p-8 text-center text-sm text-gray-500">
            {t("no_questions_added_yet")}
          </div>
        )}
      </div>
    );
  }

  // Every top-level question hidden by enable_when: explain the empty form
  // instead of a blank canvas. The edit canvas (`revealHidden`) never hits
  // this — hidden questions render there with a logic badge.
  if (!revealHidden && !hasVisibleQuestions) {
    return (
      <div className={cn("mx-auto w-full max-w-3xl", className)}>
        {header}
        <div className="p-8 text-center text-sm text-gray-500">
          {t("no_visible_questions")}
        </div>
      </div>
    );
  }

  return (
    <div className={cn("mx-auto w-full max-w-3xl", className)}>
      {header}
      <div className="space-y-4 pb-4">
        {questions.map((question, index) => (
          <QuestionBlock
            key={question.id}
            question={question}
            parentId={null}
            index={index}
            siblingCount={questions.length}
            depth={0}
            number={`${index + 1}.`}
          />
        ))}
        {AppendZone && <AppendZone parentId={null} />}
      </div>
    </div>
  );
}

